//! Per-language phonemizers for the non-Polish Slavic languages.
//!
//! - `base`: hand-written base rules (maintained by hand).
//! - `engine`: shared driver (exception slice -> base rules -> CART corrections).
//! - `bg`, `cs`, `hr`, `ru`, `uk`: generated by `pipeline/codegen_rust.py` from the distilled
//!   CART trees and exception slices. Do not edit by hand.
//! - `de`: legacy German module (not part of the distillation pipeline).

pub mod base;
pub mod engine;

pub mod bg;
pub mod cs;
pub mod de;
pub mod hr;
pub mod ru;
pub mod uk;

use engine::LangSpec;

/// The distilled engine for a language code, if there is one.
pub fn spec(lang: &str) -> Option<&'static LangSpec> {
    match lang {
        "bg" | "bulgarian" => Some(&bg::SPEC),
        "cs" | "czech" => Some(&cs::SPEC),
        "hr" | "croatian" => Some(&hr::SPEC),
        "ru" | "russian" => Some(&ru::SPEC),
        "uk" | "ukrainian" => Some(&uk::SPEC),
        _ => None,
    }
}
